func _run_tests() -> void:
	var basket := await instantiate_scene("res://basket.tscn")
	if not check("basket", basket != null, "La scena basket.tscn deve istanziarsi senza errori"):
		return

	var item_scene = get_prop(basket, "item_scene")
	var rock_scene = get_prop(basket, "rock_scene")
	var ruby_scene = get_prop(basket, "ruby_scene")

	check("item_slot", item_scene is PackedScene, "La proprietà item_scene deve contenere una PackedScene assegnata nell'Inspector")
	check("rock_slot", rock_scene is PackedScene, "La proprietà rock_scene deve contenere una PackedScene assegnata nell'Inspector")
	check("ruby_slot", ruby_scene is PackedScene, "La proprietà ruby_scene deve contenere una PackedScene assegnata nell'Inspector")

	var lives_val = get_prop(basket, "lives")
	var max_lives_val = get_prop(basket, "max_lives")
	check("lives_init", lives_val == max_lives_val, "In _ready() le vite correnti devono corrispondere a max_lives")

	var color_val = get_prop(basket, "basket_color")
	check("modulate_init", basket.modulate == color_val, "In _ready() il colore modulate del cesto deve corrispondere a basket_color")

